content.text:
The degradation has one root cause: packet loss on the ts-contacts-service → ts-preserve-service connection. Preserve's calls to contacts average about 11 s while contacts' own server spans stay around 7 ms, and hubble records drops on exactly that connection.

```json
{
  "root_causes": [
    {
      "service": "ts-contacts-service",
      "fault_kind": "network_loss",
      "evidence": [
        {"kind": "trace", "sql": "SELECT 'abn' p, s.service_name callee, s.span_name, count(*) n, approx_quantile(c.duration/1e6,0.5) client_med_ms, approx_quantile(s.duration/1e6,0.5) server_med_ms, avg(c.duration/1e6) client_avg, avg(s.duration/1e6) server_avg FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE p.service_name='ts-preserve-service' AND c.span_name='GET' GROUP BY 1,2,3 UNION ALL SELECT 'norm', s.service_name, s.span_name, count(*), approx_quantile(c.duration/1e6,0.5), approx_quantile(s.duration/1e6,0.5), avg(c.duration/1e6), avg(s.duration/1e6) FROM normal_traces c JOIN normal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id JOIN normal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE p.service_name='ts-preserve-service' AND c.span_name='GET' GROUP BY 1,2,3 ORDER BY 2,1", "claim": "Preserve's client calls to contacts average ~11s in abnormal vs ~8ms normal, while contacts' server spans stay ~7ms."},
        {"kind": "metric", "sql": "SELECT time, metric, attr_source, attr_destination, value FROM abnormal_metrics_sum WHERE metric LIKE 'hubble_drop%' AND attr_destination LIKE '%preserve-service%' ORDER BY time", "claim": "Hubble drop counters rise on the ts-contacts-service pod to ts-preserve-service pod connection throughout the abnormal window."},
        {"kind": "trace", "sql": "SELECT s.service_name, s.span_name, s.attr_span_kind, count(*) n, approx_quantile(s.duration/1e6,0.5) med_ms, max(s.duration/1e6) max_ms FROM abnormal_traces s WHERE s.service_name='ts-contacts-service' AND s.attr_span_kind='Server' GROUP BY ALL", "claim": "Contacts' own server spans remain fast (median ~4-7ms, max ~900ms), so the delay is on the wire, not in contacts."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-contacts-service", "to": "ts-preserve-service", "evidence": [{"kind": "trace", "sql": "SELECT 'abn' p, c.service_name caller, c.span_name, count(*) n, approx_quantile(c.duration/1e6,0.5) med_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-preserve-service' AND c.span_name='GET' GROUP BY 1,2,3", "claim": "Preserve's outgoing GET spans to contacts are slowed, with median client time ~1.5s in abnormal period."}]},
    {"from": "ts-preserve-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT s.service_name, s.span_name, count(*) n, approx_quantile(s.duration/1e6,0.5) med_ms, max(s.duration/1e6) max_ms FROM abnormal_traces s WHERE s.service_name IN ('ts-ui-dashboard') AND s.span_name='POST /api/v1/preserveservice/preserve' GROUP BY ALL", "claim": "ui-dashboard's preserve requests slow from ~ms to median ~4.5s, max ~20s, with some errors."}]}
  ]
}
```

